//go:build amd64 && !purego

#include "textflag.h"

// The SSE2 backends keep the first 176 bytes of the vector in X5--X15 and
// process two rows at a time. SSE2 is part of the amd64 baseline. The two
// entry points differ only in their final parity reduction: one uses POPCNT,
// while the baseline variant XOR-folds to a byte and reads the architectural
// parity flag. No address or branch depends on vector bits.

// func syndromeSSE2POPCNT(out, vector, matrix *byte)
TEXT ·syndromeSSE2POPCNT(SB), NOSPLIT, $0-24
	MOVQ out+0(FP), DI
	MOVQ vector+8(FP), SI
	MOVQ matrix+16(FP), DX
	LEAQ 181(SI), R8

	MOVOU 0(SI), X5
	MOVOU 16(SI), X6
	MOVOU 32(SI), X7
	MOVOU 48(SI), X8
	MOVOU 64(SI), X9
	MOVOU 80(SI), X10
	MOVOU 96(SI), X11
	MOVOU 112(SI), X12
	MOVOU 128(SI), X13
	MOVOU 144(SI), X14
	MOVOU 160(SI), X15
	MOVL 176(SI), R14
	MOVBLZX 180(SI), R15

	MOVQ $181, R9

sse2_popcnt_byte_loop:
	XORQ R12, R12
	MOVQ $4, R11

sse2_popcnt_pair_loop:
	PXOR X0, X0
	PXOR X1, X1

	MOVOU 0(DX), X2
	PAND X5, X2
	PXOR X2, X0
	MOVOU 181(DX), X2
	PAND X5, X2
	PXOR X2, X1

	MOVOU 16(DX), X2
	PAND X6, X2
	PXOR X2, X0
	MOVOU 197(DX), X2
	PAND X6, X2
	PXOR X2, X1

	MOVOU 32(DX), X2
	PAND X7, X2
	PXOR X2, X0
	MOVOU 213(DX), X2
	PAND X7, X2
	PXOR X2, X1

	MOVOU 48(DX), X2
	PAND X8, X2
	PXOR X2, X0
	MOVOU 229(DX), X2
	PAND X8, X2
	PXOR X2, X1

	MOVOU 64(DX), X2
	PAND X9, X2
	PXOR X2, X0
	MOVOU 245(DX), X2
	PAND X9, X2
	PXOR X2, X1

	MOVOU 80(DX), X2
	PAND X10, X2
	PXOR X2, X0
	MOVOU 261(DX), X2
	PAND X10, X2
	PXOR X2, X1

	MOVOU 96(DX), X2
	PAND X11, X2
	PXOR X2, X0
	MOVOU 277(DX), X2
	PAND X11, X2
	PXOR X2, X1

	MOVOU 112(DX), X2
	PAND X12, X2
	PXOR X2, X0
	MOVOU 293(DX), X2
	PAND X12, X2
	PXOR X2, X1

	MOVOU 128(DX), X2
	PAND X13, X2
	PXOR X2, X0
	MOVOU 309(DX), X2
	PAND X13, X2
	PXOR X2, X1

	MOVOU 144(DX), X2
	PAND X14, X2
	PXOR X2, X0
	MOVOU 325(DX), X2
	PAND X14, X2
	PXOR X2, X1

	MOVOU 160(DX), X2
	PAND X15, X2
	PXOR X2, X0
	MOVOU 341(DX), X2
	PAND X15, X2
	PXOR X2, X1

	PSHUFD $0x4e, X0, X2
	PXOR X2, X0
	MOVQ X0, AX
	MOVL 176(DX), BX
	ANDL R14, BX
	XORQ BX, AX
	MOVBLZX 180(DX), BX
	ANDQ R15, BX
	XORQ BX, AX

	PSHUFD $0x4e, X1, X2
	PXOR X2, X1
	MOVQ X1, R10
	MOVL 357(DX), BX
	ANDL R14, BX
	XORQ BX, R10
	MOVBLZX 361(DX), BX
	ANDQ R15, BX
	XORQ BX, R10

	POPCNTQ AX, AX
	ANDQ $1, AX
	SHLQ $1, R12
	ORQ AX, R12

	POPCNTQ R10, AX
	ANDQ $1, AX
	SHLQ $1, R12
	ORQ AX, R12

	ADDQ $362, DX
	DECQ R11
	JNZ sse2_popcnt_pair_loop

	MOVBLZX (R8), AX
	XORQ R12, AX
	MOVB AX, (DI)
	INCQ R8
	INCQ DI
	DECQ R9
	JNZ sse2_popcnt_byte_loop
	RET

// func syndromeSSE2(out, vector, matrix *byte)
TEXT ·syndromeSSE2(SB), NOSPLIT, $0-24
	MOVQ out+0(FP), DI
	MOVQ vector+8(FP), SI
	MOVQ matrix+16(FP), DX
	LEAQ 181(SI), R8

	MOVOU 0(SI), X5
	MOVOU 16(SI), X6
	MOVOU 32(SI), X7
	MOVOU 48(SI), X8
	MOVOU 64(SI), X9
	MOVOU 80(SI), X10
	MOVOU 96(SI), X11
	MOVOU 112(SI), X12
	MOVOU 128(SI), X13
	MOVOU 144(SI), X14
	MOVOU 160(SI), X15
	MOVL 176(SI), R14
	MOVBLZX 180(SI), R15

	MOVQ $181, R9

sse2_byte_loop:
	XORQ R12, R12
	MOVQ $4, R11

sse2_pair_loop:
	PXOR X0, X0
	PXOR X1, X1

	MOVOU 0(DX), X2
	PAND X5, X2
	PXOR X2, X0
	MOVOU 181(DX), X2
	PAND X5, X2
	PXOR X2, X1

	MOVOU 16(DX), X2
	PAND X6, X2
	PXOR X2, X0
	MOVOU 197(DX), X2
	PAND X6, X2
	PXOR X2, X1

	MOVOU 32(DX), X2
	PAND X7, X2
	PXOR X2, X0
	MOVOU 213(DX), X2
	PAND X7, X2
	PXOR X2, X1

	MOVOU 48(DX), X2
	PAND X8, X2
	PXOR X2, X0
	MOVOU 229(DX), X2
	PAND X8, X2
	PXOR X2, X1

	MOVOU 64(DX), X2
	PAND X9, X2
	PXOR X2, X0
	MOVOU 245(DX), X2
	PAND X9, X2
	PXOR X2, X1

	MOVOU 80(DX), X2
	PAND X10, X2
	PXOR X2, X0
	MOVOU 261(DX), X2
	PAND X10, X2
	PXOR X2, X1

	MOVOU 96(DX), X2
	PAND X11, X2
	PXOR X2, X0
	MOVOU 277(DX), X2
	PAND X11, X2
	PXOR X2, X1

	MOVOU 112(DX), X2
	PAND X12, X2
	PXOR X2, X0
	MOVOU 293(DX), X2
	PAND X12, X2
	PXOR X2, X1

	MOVOU 128(DX), X2
	PAND X13, X2
	PXOR X2, X0
	MOVOU 309(DX), X2
	PAND X13, X2
	PXOR X2, X1

	MOVOU 144(DX), X2
	PAND X14, X2
	PXOR X2, X0
	MOVOU 325(DX), X2
	PAND X14, X2
	PXOR X2, X1

	MOVOU 160(DX), X2
	PAND X15, X2
	PXOR X2, X0
	MOVOU 341(DX), X2
	PAND X15, X2
	PXOR X2, X1

	PSHUFD $0x4e, X0, X2
	PXOR X2, X0
	MOVQ X0, AX
	MOVL 176(DX), BX
	ANDL R14, BX
	XORQ BX, AX
	MOVBLZX 180(DX), BX
	ANDQ R15, BX
	XORQ BX, AX

	PSHUFD $0x4e, X1, X2
	PXOR X2, X1
	MOVQ X1, R10
	MOVL 357(DX), BX
	ANDL R14, BX
	XORQ BX, R10
	MOVBLZX 361(DX), BX
	ANDQ R15, BX
	XORQ BX, R10

	MOVQ AX, BX
	SHRQ $32, BX
	XORQ BX, AX
	MOVQ AX, BX
	SHRQ $16, BX
	XORQ BX, AX
	MOVQ AX, BX
	SHRQ $8, BX
	XORQ BX, AX
	TESTB AL, AL
	SETPC AL
	MOVBLZX AL, AX
	SHLQ $1, R12
	ORQ AX, R12

	MOVQ R10, AX
	MOVQ AX, BX
	SHRQ $32, BX
	XORQ BX, AX
	MOVQ AX, BX
	SHRQ $16, BX
	XORQ BX, AX
	MOVQ AX, BX
	SHRQ $8, BX
	XORQ BX, AX
	TESTB AL, AL
	SETPC AL
	MOVBLZX AL, AX
	SHLQ $1, R12
	ORQ AX, R12

	ADDQ $362, DX
	DECQ R11
	JNZ sse2_pair_loop

	MOVBLZX (R8), AX
	XORQ R12, AX
	MOVB AX, (DI)
	INCQ R8
	INCQ DI
	DECQ R9
	JNZ sse2_byte_loop
	RET
